/** The union of every command id the native side registers. */
export type TaruiCommandId = keyof TaruiCommandContracts;

/** The argument type of a command. */
export type TaruiCommandInput<TCommand extends TaruiCommandId> =
  TaruiCommandTypes[TCommand]['input'];

/** The result type of a command. */
export type TaruiCommandResult<TCommand extends TaruiCommandId> =
  TaruiCommandTypes[TCommand]['output'];
